//! Binary patch formats generated by 02_Scripts/make_patcher_assets.py.

pub const MANIFEST: &[u8] = include_bytes!("../assets/manifest.bin");
pub const EXE_PATCH: &[u8] = include_bytes!("../assets/exe_patch.bin");
pub const WAD_PATCH: &[u8] = include_bytes!("../assets/wad_patch.bin");
pub const GPC_PATCH: &[u8] = include_bytes!("../assets/gpc_patch.bin");

struct R {
    d: &'static [u8],
    p: usize,
}

impl R {
    fn new(d: &'static [u8]) -> Self {
        Self { d, p: 0 }
    }
    fn take(&mut self, n: usize) -> Result<&'static [u8], String> {
        if self.p + n > self.d.len() {
            return Err(format!("patch data truncated at {:#x} (need {})", self.p, n));
        }
        let s = &self.d[self.p..self.p + n];
        self.p += n;
        Ok(s)
    }
    fn u32(&mut self) -> Result<u32, String> {
        let b = self.take(4)?;
        Ok(u32::from_le_bytes([b[0], b[1], b[2], b[3]]))
    }
    fn u64(&mut self) -> Result<u64, String> {
        let b = self.take(8)?;
        Ok(u64::from_le_bytes([
            b[0], b[1], b[2], b[3], b[4], b[5], b[6], b[7],
        ]))
    }
    fn string(&mut self) -> Result<String, String> {
        let n = self.u32()? as usize;
        let b = self.take(n)?;
        String::from_utf8(b.to_vec()).map_err(|_| "patch string is not UTF-8".to_string())
    }
    fn magic(&mut self, want: &[u8; 8]) -> Result<(), String> {
        let got = self.take(8)?;
        if got != want {
            return Err("unexpected patch file magic".to_string());
        }
        Ok(())
    }
    fn done(&self) -> Result<(), String> {
        if self.p != self.d.len() {
            return Err(format!(
                "patch data has {} trailing bytes",
                self.d.len() - self.p
            ));
        }
        Ok(())
    }
}

#[derive(Clone)]
pub struct GpcMeta {
    pub name: String,
    pub size: u64,
    pub sha: [u8; 32],
}

pub struct Manifest {
    pub version: String,
    pub orig_exe_size: u64,
    pub orig_exe_sha: [u8; 32],
    pub orig_wad_size: u64,
    pub orig_wad_sha: [u8; 32],
    pub patched_exe_size: u64,
    pub patched_exe_sha: [u8; 32],
    pub patched_wad_size: u64,
    pub patched_wad_sha: [u8; 32],
    pub gpc: Vec<GpcMeta>,
}

fn sha_arr(r: &mut R) -> Result<[u8; 32], String> {
    let b = r.take(32)?;
    let mut h = [0u8; 32];
    h.copy_from_slice(b);
    Ok(h)
}

pub fn parse_manifest() -> Result<Manifest, String> {
    let mut r = R::new(MANIFEST);
    r.magic(b"GPMF1\0\0\0")?;
    let version = r.string()?;
    let orig_exe_size = r.u64()?;
    let orig_exe_sha = sha_arr(&mut r)?;
    let orig_wad_size = r.u64()?;
    let orig_wad_sha = sha_arr(&mut r)?;
    let patched_exe_size = r.u64()?;
    let patched_exe_sha = sha_arr(&mut r)?;
    let patched_wad_size = r.u64()?;
    let patched_wad_sha = sha_arr(&mut r)?;
    let n = r.u32()? as usize;
    let mut gpc = Vec::with_capacity(n);
    for _ in 0..n {
        let name = r.string()?;
        let size = r.u64()?;
        let sha = sha_arr(&mut r)?;
        gpc.push(GpcMeta { name, size, sha });
    }
    r.done()?;
    Ok(Manifest {
        version,
        orig_exe_size,
        orig_exe_sha,
        orig_wad_size,
        orig_wad_sha,
        patched_exe_size,
        patched_exe_sha,
        patched_wad_size,
        patched_wad_sha,
        gpc,
    })
}

pub struct ExePatch {
    pub writes: Vec<(u32, &'static [u8])>,
    pub append_offset: u32,
    pub append: &'static [u8],
}

pub fn parse_exe_patch() -> Result<ExePatch, String> {
    let mut r = R::new(EXE_PATCH);
    r.magic(b"GPEX1\0\0\0")?;
    let n = r.u32()? as usize;
    let mut writes = Vec::with_capacity(n);
    for _ in 0..n {
        let off = r.u32()?;
        let len = r.u32()? as usize;
        let data = r.take(len)?;
        writes.push((off, data));
    }
    let append_offset = r.u32()?;
    let append_len = r.u32()? as usize;
    let append = r.take(append_len)?;
    r.done()?;
    Ok(ExePatch {
        writes,
        append_offset,
        append,
    })
}

pub struct WadEntryPatch {
    pub name: String,
    /// 0 = full replacement, 1 = range diff against the original entry.
    pub mode: u32,
    pub original_size: u32,
    pub patched_size: u32,
    pub full: &'static [u8],
    pub ranges: Vec<(u32, &'static [u8])>,
}

pub struct WadPatch {
    pub entries: Vec<WadEntryPatch>,
}

pub fn parse_wad_patch() -> Result<WadPatch, String> {
    let mut r = R::new(WAD_PATCH);
    r.magic(b"GPWD1\0\0\0")?;
    let n = r.u32()? as usize;
    let mut entries = Vec::with_capacity(n);
    for _ in 0..n {
        let name = r.string()?;
        let mode = r.u32()?;
        let original_size = r.u32()?;
        let patched_size = r.u32()?;
        let mut full: &'static [u8] = &[];
        let mut ranges = Vec::new();
        if mode == 0 {
            full = r.take(patched_size as usize)?;
        } else if mode == 1 {
            let rc = r.u32()? as usize;
            ranges.reserve(rc);
            for _ in 0..rc {
                let off = r.u32()?;
                let len = r.u32()? as usize;
                let data = r.take(len)?;
                ranges.push((off, data));
            }
        } else {
            return Err(format!("unknown WAD patch mode {} for {}", mode, name));
        }
        entries.push(WadEntryPatch {
            name,
            mode,
            original_size,
            patched_size,
            full,
            ranges,
        });
    }
    r.done()?;
    Ok(WadPatch { entries })
}

pub struct GpcFile {
    pub name: String,
    pub data: &'static [u8],
}

pub fn parse_gpc_patch() -> Result<Vec<GpcFile>, String> {
    let mut r = R::new(GPC_PATCH);
    r.magic(b"GPGC1\0\0\0")?;
    let n = r.u32()? as usize;
    let mut files = Vec::with_capacity(n);
    for _ in 0..n {
        let name = r.string()?;
        let len = r.u32()? as usize;
        let data = r.take(len)?;
        files.push(GpcFile { name, data });
    }
    r.done()?;
    Ok(files)
}
